def member_checkout(amount, vip_rate, coupon):
    """规则：先按 vip_rate（如 0.9）打折，再减 coupon。结果不低于 0。"""
    return max(0.0, (amount - coupon) * vip_rate)

verification_tests:
from target import member_checkout

def test_only_vip():
    assert member_checkout(100, 0.9, 0) == 90.0

def test_only_coupon():
    assert member_checkout(100, 1.0, 20) == 80.0

def test_combined_order():
    assert member_checkout(200, 0.9, 30) == 150.0
